import fs from 'node:fs'
import path from 'node:path'
import type { AstroIntegration } from 'astro'
import { getDatabase, downloadFile } from '../lib/notion/client'
import { filePath } from '../lib/blog-helpers'

const GENERATED_FILE = path.resolve('./src/generated/cover-image.ts')

const writeGeneratedFile = (url: string) => {
  const content = `// Auto-generated by src/integrations/cover-image-downloader.ts at build time.
// Do not edit manually. The default empty value is used until the first build.
export const COVER_IMAGE_URL: string = ${JSON.stringify(url)}
`
  fs.mkdirSync(path.dirname(GENERATED_FILE), { recursive: true })
  fs.writeFileSync(GENERATED_FILE, content)
}

export default (): AstroIntegration => ({
  name: 'cover-image-downloader',
  hooks: {
    'astro:build:start': async () => {
      const database = await getDatabase()

      if (!database.Cover) {
        writeGeneratedFile('')
        return Promise.resolve()
      }

      if (database.Cover.Type === 'external') {
        writeGeneratedFile(database.Cover.Url)
        return Promise.resolve()
      }

      if (database.Cover.Type !== 'file') {
        writeGeneratedFile('')
        return Promise.resolve()
      }

      let url!: URL
      try {
        url = new URL(database.Cover.Url)
      } catch {
        console.log('Invalid Cover image URL: ', database.Cover?.Url)
        writeGeneratedFile('')
        return Promise.resolve()
      }

      writeGeneratedFile(filePath(url))
      return downloadFile(url)
    },
  },
})
